  return { published, ctx, repo, uc: new CreateTask(repo) };
}

describe('create_task', () => {
  test(covers(['usecase:create_task', 'method:Task.create', 'criterion:0001/persistencia-criacao'], 'salva, publica TaskCreated, retorna pending e rejeita duplicado'), async () => {
